function canSkipGem(state, it, speed, wasJumping = false) {
  if (state.jumpMs === null && !wasJumping) return false;
  const c = state.config;
  const skipH = c.gem?.skipHeightM ?? 0.25;

  // Airborne and above skip height: skip it
  if (state.jumpY >= skipH) return true;

  // Airborne and moving upwards: jump will peak above skip height (same as barrier vaulting)
  const g = c.jump.gravity * (state.drop ? c.jump.dropGravityFactor : 1);
